#!/usr/bin/env bash
# Question 13: Unhealthy worker. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q13_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q13_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q13_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: DaemonSet
metadata:
  name: node-probe
  namespace: ${Q13_NS}
spec:
  selector:
    matchLabels: { app: node-probe }
  template:
    metadata:
      labels: { app: node-probe }
    spec:
      containers:
        - name: probe
          image: registry.k8s.io/pause:3.10
          resources:
            requests: { cpu: 10m, memory: 8Mi }
EOF
kubectl -n "${Q13_NS}" rollout status daemonset/node-probe --timeout=240s

case "${Q13_FAULT}" in
  kubelet-stopped) ;;
  containerd-stopped) ;;
  ip-forward-and-containerd) ;;
  kubelet-binary-path) ;;
  cordoned)
    kubectl cordon "${Q13_NODE}"
    ;;
  stray-taint)
    kubectl taint node "${Q13_NODE}" maintenance=true:NoSchedule --overwrite
    kubectl -n "${Q13_NS}" delete pod -l app=node-probe --field-selector "spec.nodeName=${Q13_NODE}" --wait=false
    ;;
  kubelet-config-invalid) ;;
  kubelet-api-port) ;;
  kubelet-extra-args) ;;
  cni-config-removed) ;;
  containerd-config-invalid) ;;
  kubelet-conf-missing) ;;
  kubelet-swap-on) ;;
  cni-conflist-typo) ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac
